function activityStatus(d){
  if(d.agency_mode==="mixed")return "mixed";
  if(d.activity_status)return d.activity_status;
  if(d.recent_activity_2025||d.recent_activity_year)return "recent";
  return "unknown";
}
function activityLabel(d){
  const s=activityStatus(d);
  if(s==="active")return "現役確認済み";
  if(s==="dissolved")return d.activity_end?`解散 ${d.activity_end}`:"解散確認済み";
  if(s==="mixed")return d.affiliation_note?"所属・編成要確認":"複数所属／一部フリー";
  if(s==="paused")return "活動休止";
  if(s==="recent")return `${d.recent_activity_year||2025}活動確認`;
  return d.activity_research_status==="UNRESOLVED"?"活動状態 UNRESOLVED":"活動状態 未確認";
}


