function conversion(o,startYear){const vals=Object.entries(o||{}).filter(([y])=>Number(y)>=startYear&&Number(y)<=2025).map(([,v])=>v),qf=vals.filter(v=>rank(v)>=50).length,sf=vals.filter(v=>rank(v)>=70).length,fin=vals.filter(v=>rank(v)>=90).length;return{qf,sf,fin,qfToSf:qf?sf/qf*100:0,sfToFinal:sf?fin/sf*100:0}}
const CAREER_CACHE=new WeakMap();function careerStats(d){if(CAREER_CACHE.has(d))return CAREER_CACHE.get(d);const m1=baseContestScore(d.m1),koc=baseContestScore(d.koc),total=m1+koc,appearances=Object.keys(d.m1||{}).length+Object.keys(d.koc||{}).length,all=[...Object.values(d.m1||{}),...Object.values(d.koc||{})],peak=Math.max(0,...all.map(baseScore)),dual=m1&&koc?2*m1*koc/(m1+koc):0,m1Progress=conversion(d.m1,2015),kocProgress=conversion(d.koc,2017),qf=m1Progress.qf+kocProgress.qf,sf=m1Progress.sf+kocProgress.sf,qfToSf=qf?sf/qf*100:0,streak=Math.max(longestStreak(d.m1,m1Years),longestStreak(d.koc,kocYears)),sfStreak=Math.max(longestStreak(d.m1,m1Years,70),longestStreak(d.koc,kocYears,70)),comeback=hasComeback(d.m1,m1Years)||hasComeback(d.koc,kocYears),value={m1,koc,total,appearances,average:appearances?total/appearances:0,peak,dual,m1Progress,kocProgress,qfToSf,streak,sfStreak,comeback};CAREER_CACHE.set(d,value);return value}
function qualifiedQfRate(d){const c=careerStats(d),n=c.m1Progress.qf+c.kocProgress.qf;return n>=3?c.qfToSf:-1}
function periodDual(d){const s=scoreStats(d);return s.m1&&s.koc?2*s.m1*s.koc/(s.m1+s.koc):0}
function careerTypes(d){const c=careerStats(d),tags=[],share=c.total?c.m1/c.total:.5,upper=nAt(d.m1,50)+nAt(d.koc,50),final=hasFinal(d.m1)||hasFinal(d.koc);if(c.dual>=20)tags.push("二刀流");if(c.total&&share>=.75)tags.push("漫才特化");else if(c.total&&share<=.25)tags.push("コント特化");if(!final&&upper>=5)tags.push("門番型");if(c.appearances>=8&&c.average>=3.5)tags.push("安定型");if(c.appearances<=3&&c.peak>=7)tags.push("一撃型");if(c.comeback)tags.push("復活型");return tags}
