function renderAgencyDashboard(filtered){const verified=filtered.filter(d=>d.agency_verified&&d.agency),dissolved=filtered.filter(d=>activityStatus(d)==="dissolved"),activeVerified=filtered.filter(d=>d.agency_verified&&d.agency&&["active","mixed"].includes(activityStatus(d))),statusVerified=filtered.filter(d=>d.activity_verified||d.recent_activity_verified||d.recent_activity_year||["active","dissolved","mixed"].includes(activityStatus(d))),by=new Map();for(const d of verified){const k=d.agency;if(!by.has(k))by.set(k,[]);by.get(k).push(d)}const rows=[...by.entries()].map(([agency,ds])=>{const finals=ds.filter(d=>hasFinal(d.m1)||hasFinal(d.koc)).length,young=ds.filter(d=>{const y=careerYears(d);return y!=null&&y<=15}).length,avg=ds.length?ds.reduce((a,d)=>a+scoreStats(d).extended,0)/ds.length:0,total=ds.reduce((a,d)=>a+scoreStats(d).extended,0);return{agency,n:ds.length,finals,young,avg,total}}).sort((a,b)=>b.total-a.total||b.n-a.n);const max=Math.max(1,...rows.map(r=>r.total));$("#agencyCoverage").innerHTML=`所属確認済み <b>${verified.length}</b> / ${filtered.length}組（${filtered.length?Math.round(verified.length/filtered.length*100):0}%） ／ 活動状態確認 ${statusVerified.length}組（${filtered.length?Math.round(statusVerified.length/filtered.length*100):0}%） ／ 現役扱い＋所属確認 ${activeVerified.length}組${dissolved.length?` ／ 解散確認済み ${dissolved.length}組`:""}`;$("#agencyTableWrap").innerHTML=rows.length?`<table class="agencytable"><thead><tr><th>事務所</th><th>確認組数</th><th>拡張点合計</th><th>1組平均</th><th>決勝経験率</th><th>若手15年以下</th></tr></thead><tbody>${rows.slice(0,20).map(r=>`<tr><td><strong>${esc(r.agency)}</strong><span class="agencybar" style="width:${Math.max(3,r.total/max*90)}px"></span></td><td>${r.n}</td><td>${r.total.toFixed(0)}</td><td>${r.avg.toFixed(1)}</td><td>${r.n?Math.round(r.finals/r.n*100):0}%</td><td>${r.young}</td></tr>`).join('')}</tbody></table>`:'<div class="empty" style="padding:28px">現在条件では所属確認済みデータがありません。</div>'}
